import sys

def getInput():
	return sys.stdin.readline().strip()

def getInt():
	return int(getInput())

def getInts():
	return map(int, getInput().split())

def getArray():
	return list(getInts())
tc = getInt()
for _ in range(tc):
	n = getInt()
	lines = []
	for __ in range(n):
		lines.append(getArray()[1:])
	mp = dict()
	for line in lines:
		for ant in line:
			if abs(ant) in mp:
				mp[abs(ant)] += 1
			else:
				mp[abs(ant)] = 1
	ans = 0
	for i in mp.values():
		if i >= 2:
			ans += 1
	for line in lines:
		neg = []
		pos = []
		for ant in line:
			if ant < 0:
				neg.append(ant)
			else:
				pos.append(ant)
		pos.reverse()
		while True:
			try:
				if abs(neg[-1]) < pos[-1]:
					closest = neg[-1]
				else:
					closest = pos[-1]
			except:
				if not neg and (not pos):
					break
				if not neg:
					closest = pos[-1]
				if not pos:
					closest = neg[-1]
			if mp[abs(closest)] >= 2:
				if closest < 0:
					ans += len(neg) - 1
				else:
					ans += len(pos) - 1
			elif closest < 0:
				ans += len(pos)
			else:
				ans += len(neg)
			if closest < 0:
				neg.pop()
			else:
				pos.pop()
	print(ans)
